query:
NODE VALUE incoming SumAgg<INT64> = 0
TABLE result {id STRING, total INT64}

MATCH (s:player)-[e:follow]->(t:player)
PER PATH {
  SET t.@incoming += coalesce(e.degree, 0)
}

MATCH (p:player)
PER NODE (p) {
  EXPORT p.id AS id, p.@incoming AS total INTO result
}

FOR r IN result
RETURN r.id AS id, r.total AS total
